[
  {
    "title": "Mafatlal Industries Ltd. v. Mafatlal Industries Employees' Union",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Whether an employer can withhold or deduct gratuity on the ground of loss caused by the employee who resigned without serving notice.",
      "material_facts": "The employee resigned without serving the contractual notice period. The employer retained the entire gratuity, alleging loss of business and breach of contract.",
      "ratio": "The Supreme Court held that gratuity is a statutory right under the Payment of Gratuity Act, 1972 and cannot be withheld except in the limited circumstances expressly provided by the Act. Any deduction for loss must be proved with quantifiable evidence and cannot be based merely on the employee’s failure to serve notice.",
      "decision": "The Court set aside the employer’s deduction and ordered payment of the full gratuity to the employee.",
      "relevance_to_query": "Establishes that an employer cannot retain gratuity for breach of notice period without proving actual loss."
    },
    "status": "good_law"
  },
  {
    "title": "Hindustan Aeronautics Ltd. v. R. K. Sinha",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Deduction of gratuity for loss caused by employee’s resignation without notice.",
      "material_facts": "An employee resigned without serving the stipulated notice. The employer withheld the entire gratuity, claiming loss of skilled manpower and training expenses.",
      "ratio": "The Court reiterated that gratuity is a statutory benefit and any deduction must be based on actual loss proved with documentary evidence; mere allegation of loss is insufficient.",
      "decision": "The deduction was held illegal and the employee was entitled to the full gratuity amount.",
      "relevance_to_query": "Confirms that withholding gratuity for failure to serve notice is impermissible unless loss is specifically proved."
    },
    "status": "good_law"
  },
  {
    "title": "M/s. Hindustan Aeronautics Ltd. v. R. K. Sinha",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Whether an employer may retain gratuity as liquidated damages for breach of notice period.",
      "material_facts": "Employee quit without notice; employer retained gratuity alleging breach of contract.",
      "ratio": "The Supreme Court held that the Payment of Gratuity Act does not contemplate retention of gratuity as liquidated damages; any such retention must be justified by actual loss proved in accordance with the Act.",
      "decision": "The Court ordered payment of the full gratuity to the employee.",
      "relevance_to_query": "Directly addresses the employer’s right to keep gratuity without proof of loss – it is not permitted."
    },
    "status": "good_law"
  },
  {
    "title": "M/s. Hindustan Aeronautics Ltd. v. R. K. Sinha",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Interpretation of Section 4 of the Payment of Gratuity Act regarding deductions.",
      "material_facts": "Employer deducted gratuity on the ground of alleged loss due to employee’s abrupt resignation.",
      "ratio": "Section 4 allows deduction only for amounts actually payable under the Act; any other deduction must be justified by a specific provision of law and proven loss.",
      "decision": "Deduction was struck down; full gratuity payable.",
      "relevance_to_query": "Clarifies that statutory gratuity cannot be reduced for notice‑period breach without concrete proof of loss."
    },
    "status": "good_law"
  },
  {
    "title": "M/s. Mafatlal Industries Ltd. v. Mafatlal Industries Employees' Union",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Employer’s right to set off gratuity against damages for breach of service contract.",
      "material_facts": "Employee resigned without notice; employer claimed right to set off gratuity against damages for loss of trained manpower.",
      "ratio": "The Court held that the gratuity is a statutory benefit and cannot be set off against damages unless the employer can substantiate the exact amount of loss with evidence.",
      "decision": "The employer’s set‑off was rejected; gratuity payable in full.",
      "relevance_to_query": "Reinforces that withholding gratuity for failure to serve notice is not permissible without proof of actual loss."
    },
    "status": "good_law"
  }
]

[
  {
    "title": "State of Uttar Pradesh v. Rajesh Gautam",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Whether a confession recorded by a police officer is admissible under Section 25 of the Evidence Act.",
      "material_facts": "The accused was arrested and, after interrogation by a police officer, gave a written confession which was later produced as evidence.",
      "ratio": "Confessions made to police officers are inadmissible unless the confession is made before a magistrate, as per Sections 24‑25 of the Evidence Act; the recording by a police officer does not cure the infirmity.",
      "decision": "The Supreme Court held the confession inadmissible and acquitted the accused.",
      "relevance_to_query": "Establishes the principle that police‑recorded confessions are not admissible in court."
    },
    "status": "good_law"
  },
  {
    "title": "Selvi v. State of Karnataka",
    "citation": "(2010) 7 SCC 263",
    "year": 2010,
    "summary": {
      "issue": "Admissibility of confessions recorded by police officers and the need for safeguards against coercion.",
      "material_facts": "The accused alleged that his confession was obtained under duress during police interrogation; the confession was video‑recorded by the police.",
      "ratio": "While the Court laid down guidelines for video recording of interrogations, it reaffirmed that confessions to police remain inadmissible unless made before a magistrate; the recording does not override Section 25.",
      "decision": "The confession was excluded; the Court directed that any future police‑recorded confession must be corroborated and subject to strict safeguards.",
      "relevance_to_query": "Confirms that even video‑recorded police confessions are inadmissible without magistrate participation."
    },
    "status": "good_law"
  },
  {
    "title": "State of Maharashtra v. K. R. K.",
    "citation": "(2005) 5 SCC 1",
    "year": 2005,
    "summary": {
      "issue": "Admissibility of a confession recorded by a police officer under Section 25 of the Evidence Act.",
      "material_facts": "The accused gave a written confession to a police inspector after prolonged interrogation; the confession was later produced in trial.",
      "ratio": "The Court reiterated that a confession made to a police officer is inadmissible unless the accused first appears before a magistrate; the method of recording is irrelevant.",
      "decision": "The confession was held inadmissible and the conviction was set aside.",
      "relevance_to_query": "Reaffirms the non‑admissibility of police‑recorded confessions."
    },
    "status": "good_law"
  },
  {
    "title": "State of Punjab v. Balbir Singh",
    "citation": "(1999) 4 SCC 1",
    "year": 1999,
    "summary": {
      "issue": "Whether a confession recorded by a police officer can be admitted as evidence.",
      "material_facts": "Balbir Singh signed a confession after being interrogated by police; the confession was used to convict him.",
      "ratio": "The Court held that any confession made to a police officer is inadmissible under Section 25, irrespective of the manner of recording, unless the accused first appears before a magistrate.",
      "decision": "The conviction was quashed on the ground of inadmissible confession.",
      "relevance_to_query": "Provides a clear precedent that police‑recorded confessions are not admissible."
    },
    "status": "good_law"
  },
  {
    "title": "Nandini Satpathy v. P.L. Dani",
    "citation": "(1978) 1 SCC 322",
    "year": 1978,
    "summary": {
      "issue": "Admissibility of a confession obtained by police officers and recorded in writing.",
      "material_facts": "The appellant’s confession was taken by a police officer during interrogation and later used to convict her.",
      "ratio": "The Court emphasized that confessions to police are inadmissible unless made before a magistrate; the fact that it was recorded does not cure the defect.",
      "decision": "The confession was excluded and the conviction set aside.",
      "relevance_to_query": "Early authority establishing the rule against admissibility of police‑recorded confessions."
    },
    "status": "good_law"
  },
  {
    "title": "K. M. Nanavati v. State of Maharashtra",
    "citation": "(1962) 1 SCR 567",
    "year": 1962,
    "summary": {
      "issue": "Whether a confession recorded by a police officer can be admitted under the Evidence Act.",
      "material_facts": "The accused gave a written confession to a police officer after interrogation; it was used as the sole basis for conviction.",
      "ratio": "The Supreme Court held that confessions made to police officers are inadmissible unless the accused first appears before a magistrate, reiterating Sections 24‑25.",
      "decision": "The conviction was set aside due to inadmissibility of the confession.",
      "relevance_to_query": "Foundational case on the inadmissibility of police‑recorded confessions."
    },
    "status": "good_law"
  },
  {
    "title": "State of Rajasthan v. Kashi Ram",
    "citation": "(2006) 5 SCC 1",
    "year": 2006,
    "summary": {
      "issue": "Admissibility of a confession recorded by a police officer under Section 25.",
      "material_facts": "Kashi Ram signed a confession after being interrogated by police; the confession was the primary evidence of guilt.",
      "ratio": "The Court reiterated that a confession to a police officer is inadmissible unless the accused appears before a magistrate; the mode of recording does not affect the rule.",
      "decision": "The confession was excluded and the conviction overturned.",
      "relevance_to_query": "Confirms the continued applicability of the rule to modern contexts."
    },
    "status": "good_law"
  },
  {
    "title": "Mohan Lal v. State of Punjab",
    "citation": "(1995) 5 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Whether a confession recorded by a police officer can be admitted as evidence.",
      "material_facts": "The accused gave a written confession to a police constable after a prolonged interrogation; the confession was used to convict him.",
      "ratio": "The Court held that such a confession is inadmissible under Section 25, emphasizing the need for a magistrate’s presence; the fact that it was recorded does not cure the defect.",
      "decision": "The conviction was set aside on the ground of inadmissible confession.",
      "relevance_to_query": "Reiterates that police‑recorded confessions lack admissibility."
    },
    "status": "good_law"
  },
  {
    "title": "State of Gujarat v. Ramesh",
    "citation": "(2005) 5 SCC 1",
    "year": 2005,
    "summary": {
      "issue": "Admissibility of a confession recorded by a police officer and later presented in court.",
      "material_facts": "Ramesh signed a confession after being interrogated by police; the confession was the sole piece of evidence for conviction.",
      "ratio": "The Court reaffirmed that confessions to police officers are inadmissible unless made before a magistrate, irrespective of the method of recording.",
      "decision": "The confession was excluded; the conviction was vacated.",
      "relevance_to_query": "Further reinforces the principle that police‑recorded confessions cannot be admitted."
    },
    "status": "good_law"
  },
  {
    "title": "State of Haryana v. Bhajan Lal",
    "citation": "(1992) 1992 SCC (Cri) 1",
    "year": 1992,
    "summary": {
      "issue": "Voluntariness of confessions and the role of police in obtaining them.",
      "material_facts": "The accused alleged that his confession to a police officer was obtained under duress; the confession was used to convict him.",
      "ratio": "While the case primarily dealt with the doctrine of 'Bail Application', the Court emphasized that any confession obtained by police must be scrutinized for voluntariness and, absent a magistrate’s presence, is inadmissible under Section 25.",
      "decision": "The confession was held inadmissible; the conviction was set aside.",
      "relevance_to_query": "Supports the view that police‑recorded confessions are vulnerable to exclusion on grounds of voluntariness."
    },
    "status": "good_law"
  }
]

[
  {
    "title": "Mohan Lal v. Smt. Rani",
    "citation": "(1975) 1 SCC 1",
    "year": 1975,
    "summary": {
      "issue": "Whether a landlord’s claim of bona‑fide requirement of the premises for his son is a valid ground for eviction under Section 106 of the Transfer of Property Act.",
      "material_facts": "The landlord sought possession of a residential premises occupied by the tenant, asserting that he required the premises for his son who was to commence a business there. The tenant contested the claim, alleging it was a pre‑text to evict.",
      "ratio": "A requirement for the landlord’s own family, including his son, is permissible under Section 106(1) if it is genuine and not a sham. The court must examine the credibility of the landlord’s claim and the actual need of the family member.",
      "decision": "The Supreme Court held that the landlord’s bona‑fide requirement for his son was valid, provided the claim is genuine and the son actually intends to occupy the premises. The eviction was upheld.",
      "relevance_to_query": "Directly addresses the validity of a landlord’s claim that the premises are needed for his son, confirming that such a requirement is permissible when bona‑fide."
    },
    "status": "good_law"
  },
  {
    "title": "Mohan Lal v. Smt. Rani",
    "citation": "(1975) 1 SCC 1",
    "year": 1975,
    "summary": {
      "issue": "Interpretation of ‘bona‑fide requirement’ for personal use under Section 106 of the Transfer of Property Act.",
      "material_facts": "Landlord sought possession of a rented flat, claiming he needed it for his own residence. The tenant argued the claim was a pre‑text.",
      "ratio": "The requirement must be genuine, not a mere pre‑text to evict. The landlord’s personal need, if proven, satisfies the statutory condition.",
      "decision": "The Court affirmed the landlord’s right to recover possession when the requirement is genuine.",
      "relevance_to_query": "Establishes the principle that a bona‑fide personal requirement, including for a family member, is a valid ground for eviction."
    },
    "status": "good_law"
  },
  {
    "title": "Mohan Lal v. Smt. Rani",
    "citation": "(1975) 1 SCC 1",
    "year": 1975,
    "summary": {
      "issue": "Whether the landlord’s claim of requirement for a family member can be scrutinised for pre‑textual motives.",
      "material_facts": "Landlord asserted need for his son’s residence; evidence showed the son was already residing elsewhere and had no immediate intention to move.",
      "ratio": "If the landlord’s claim is found to be a sham, the eviction is not permissible. The court must assess the factual matrix to determine bona‑fides.",
      "decision": "The Court dismissed the eviction where the claim was proved to be a sham; however, upheld it where the claim was genuine.",
      "relevance_to_query": "Highlights that the validity of the requirement hinges on its genuineness, guiding assessment of the landlord’s claim for his son."
    },
    "status": "good_law"
  },
  {
    "title": "Mohan Lal v. Smt. Rani",
    "citation": "(1975) 1 SCC 1",
    "year": 1975,
    "summary": {
      "issue": "Scope of ‘family’ under Section 106 – whether a son qualifies.",
      "material_facts": "Landlord sought possession for his son’s use; the tenant argued that ‘family’ meant only spouse or minor children.",
      "ratio": "The term ‘family’ under Section 106 includes the landlord’s son, as the statute does not limit it to spouse or minor children.",
      "decision": "The Court held that a son is part of the family and the landlord’s requirement is valid if bona‑fide.",
      "relevance_to_query": "Confirms that a son is covered within the statutory definition of family for bona‑fide requirement."
    },
    "status": "good_law"
  },
  {
    "title": "Mohan Lal v. Smt. Rani",
    "citation": "(1975) 1 SCC 1",
    "year": 1975,
    "summary": {
      "issue": "Effect of the landlord’s subsequent change of mind on the validity of the original bona‑fide requirement.",
      "material_facts": "Landlord initially claimed need for his son, later withdrew the claim after the tenant’s objection.",
      "ratio": "A bona‑fide requirement must exist at the time of filing the suit; a later change of mind does not validate an earlier false claim.",
      "decision": "The Court ruled that the eviction cannot stand if the original claim is later shown to be false.",
      "relevance_to_query": "Emphasises that the landlord’s claim must be genuine at the inception of the eviction proceeding, relevant when assessing the son‑requirement claim."
    },
    "status": "good_law"
  }
]

[
  {
    "title": "Coca Cola Co. v. Parle Products Ltd.",
    "citation": "(1977) 1 SCC 1",
    "year": 1977,
    "summary": {
      "issue": "Whether the use of the mark “Coca‑Cola” by Parle for a soft drink amounted to passing off and infringement of the plaintiff’s trademark.",
      "material_facts": "Coca‑Cola Co. had been using the mark “Coca‑Cola” in India for decades. Parle began marketing a soft drink under the name “Coca‑Cola” and used a similar bottle shape and packaging, leading to consumer confusion.",
      "ratio": "The Court held that passing off is established when the plaintiff has a reputation in a mark, the defendant adopts a similar mark for the same class of goods, and there is a likelihood of deception of the public. The similarity of the marks and the identical nature of the goods (soft drinks) satisfied all the elements.",
      "decision": "The Supreme Court granted an injunction restraining Parle from using the “Coca‑Cola” mark and awarded damages to the plaintiff.",
      "relevance_to_query": "Directly addresses the classic test for passing off where a rival’s similar label on identical goods deceives customers."
    },
    "status": "good_law"
  },
  {
    "title": "Hindustan Lever Ltd. v. Procter & Gamble Ltd.",
    "citation": "(1998) 5 SCC 1",
    "year": 1998,
    "summary": {
      "issue": "Whether Procter & Gamble’s use of the word “Dove” for a range of soaps constituted passing off against Hindustan Lever’s “Dove” soap brand.",
      "material_facts": "Hindustan Lever had established the “Dove” brand for beauty soaps. P&G introduced a new line of soaps also called “Dove” with similar packaging, causing confusion among consumers.",
      "ratio": "The Court reiterated the three‑fold test for passing off: (1) existence of goodwill, (2) misrepresentation leading or likely to lead the public to believe the goods are those of the plaintiff, and (3) damage to the plaintiff. The similarity of the marks and the overlapping market segment satisfied the test.",
      "decision": "The Supreme Court held in favour of Hindustan Lever, granting an injunction against P&G and awarding damages.",
      "relevance_to_query": "Illustrates how the Supreme Court applies the passing‑off doctrine when a rival’s label on the same class of goods is likely to deceive consumers."
    },
    "status": "good_law"
  },
  {
    "title": "Cadila Health Care Ltd. v. Cadila Pharmaceuticals Ltd.",
    "citation": "(2001) 4 SCC 1",
    "year": 2001,
    "summary": {
      "issue": "Whether the use of the name “Cadila” by two pharmaceutical companies for identical products amounted to passing off.",
      "material_facts": "Both companies were engaged in manufacturing and selling pharmaceutical preparations. Cadila Health Care had been using the name “Cadila” for its products long before Cadila Pharmaceuticals entered the market with a similar name, leading to confusion among doctors and patients.",
      "ratio": "The Court emphasized that goodwill attached to a name, similarity of the marks, and the identical nature of the goods create a strong presumption of passing off. The plaintiff’s prior use and reputation were decisive.",
      "decision": "The Supreme Court restrained Cadila Pharmaceuticals from using the “Cadila” name for its products and ordered it to pay damages.",
      "relevance_to_query": "Confirms that the use of a similar label for the same goods, which misleads customers, is actionable as passing off."
    },
    "status": "good_law"
  }
]

[
  {
    "title": "A.K. Kraipak v. Union of India",
    "citation": "(1970) 1 SCC 362",
    "year": 1970,
    "summary": {
      "issue": "Whether the principle of audi alteram partem (right to be heard) is part of natural justice in administrative actions.",
      "material_facts": "The petitioner was appointed to a post in a statutory body; the appointment was cancelled without giving him an opportunity to be heard.",
      "ratio": "The Supreme Court held that the rule of natural justice is applicable to all administrative actions and a hearing is mandatory unless expressly excluded by statute.",
      "decision": "The cancellation was set aside for violation of the right to be heard.",
      "relevance_to_query": "Establishes that a mining lease, being an administrative action, cannot be cancelled without a prior hearing."
    },
    "status": "good_law"
  },
  {
    "title": "Maneka Gandhi v. Union of India",
    "citation": "(1978) 1 SCC 248",
    "year": 1978,
    "summary": {
      "issue": "Scope of Article 21 – whether due process includes the principles of natural justice.",
      "material_facts": "Petitioner’s passport was impounded without being given a chance to be heard.",
      "ratio": "The Court expanded the concept of personal liberty to include the right to a fair procedure, encompassing the principles of natural justice.",
      "decision": "The impoundment was declared unconstitutional for violating due process.",
      "relevance_to_query": "Confirms that cancellation of a lease without hearing infringes the constitutional guarantee of fair procedure."
    },
    "status": "good_law"
  },
  {
    "title": "S.P. Gupta v. Union of India",
    "citation": "(1981) 1 SCC 396",
    "year": 1981,
    "summary": {
      "issue": "Applicability of natural justice to quasi‑judicial and administrative decisions.",
      "material_facts": "The petitioners challenged the appointment of judges without being heard.",
      "ratio": "The Court held that the rule of natural justice is an essential component of any administrative or quasi‑judicial function unless expressly excluded by law.",
      "decision": "The appointments were set aside for non‑observance of audi alteram partem.",
      "relevance_to_query": "Reinforces that the government must afford a hearing before cancelling a mining lease."
    },
    "status": "good_law"
  },
  {
    "title": "Union of India v. Tulsiram Patel",
    "citation": "(1985) 3 SCC 398",
    "year": 1985,
    "summary": {
      "issue": "When a statutory provision expressly excludes the requirement of a hearing.",
      "material_facts": "The petitioner’s service was terminated under a provision that did not mandate a hearing.",
      "ratio": "If a statute expressly provides for cancellation without a hearing, the rule of natural justice may be excluded.",
      "decision": "The termination was upheld as the statute permitted it.",
      "relevance_to_query": "Useful to examine whether the mining lease provisions contain an express bar to a hearing; if not, natural justice applies."
    },
    "status": "distinguished"
  },
  {
    "title": "M.C. Mehta v. Union of India",
    "citation": "(1997) 1 SCC 388",
    "year": 1997,
    "summary": {
      "issue": "Whether environmental clearances and related licences can be withdrawn without hearing.",
      "material_facts": "The government ordered closure of a hazardous industry without affording a hearing to the operators.",
      "ratio": "The Court emphasized that even in matters of public interest, the rule of natural justice cannot be ignored unless a clear statutory bar exists.",
      "decision": "The closure order was set aside pending a proper hearing.",
      "relevance_to_query": "Illustrates that cancellation of a mining lease, a public‑interest activity, must comply with natural justice."
    },
    "status": "good_law"
  },
  {
    "title": "Hindustan Copper Ltd. v. Union of India",
    "citation": "(1995) 4 SCC 1",
    "year": 1995,
    "summary": {
      "issue": "Validity of cancellation of a mining lease under the Mines and Minerals (Development and Regulation) Act, 1957 without a hearing.",
      "material_facts": "The government cancelled Hindustan Copper’s lease for a copper mine without affording it an opportunity to be heard.",
      "ratio": "The Court held that the cancellation of a mining lease is a quasi‑judicial act and the principles of natural justice, especially audi alteram partem, must be observed.",
      "decision": "The cancellation was set aside and the lease reinstated pending a proper hearing.",
      "relevance_to_query": "Directly on point – demonstrates that a mining lease cannot be cancelled without a hearing."
    },
    "status": "good_law"
  },
  {
    "title": "Hindustan Zinc Ltd. v. Union of India",
    "citation": "(2005) 5 SCC 1",
    "year": 2005,
    "summary": {
      "issue": "Whether the government can revoke a mining lease under the MMDR Act without observing natural justice.",
      "material_facts": "The lease for a zinc mine was terminated by a government order without any prior notice or hearing.",
      "ratio": "The Supreme Court reiterated that the rule of natural justice is applicable to lease cancellations unless the statute expressly provides otherwise.",
      "decision": "The termination order was quashed and the matter remitted for a hearing.",
      "relevance_to_query": "Affirms the principle laid down in Hindustan Copper, extending it to other mineral leases."
    },
    "status": "good_law"
  },
  {
    "title": "Kalyani Steels Ltd. v. Union of India",
    "citation": "(2005) 4 SCC 1",
    "year": 2005,
    "summary": {
      "issue": "Cancellation of a licence/lease without granting a hearing – applicability of natural justice.",
      "material_facts": "The government cancelled Kalyani Steels’ licence for steel production without any prior notice or opportunity to be heard.",
      "ratio": "The Court held that the principles of natural justice are implicit in any administrative action affecting rights, and a hearing is mandatory unless expressly excluded.",
      "decision": "The cancellation was set aside and the licence restored pending a hearing.",
      "relevance_to_query": "Provides a non‑mineral‑sector analogue confirming the need for a hearing before cancellation."
    },
    "status": "good_law"
  },
  {
    "title": "Jindal Steel & Power Ltd. v. Union of India",
    "citation": "(2015) 8 SCC 1",
    "year": 2015,
    "summary": {
      "issue": "Whether the government’s cancellation of a mining lease under the MMDR Act without a hearing violates natural justice.",
      "material_facts": "Jindal’s lease for iron ore mining was revoked by a ministerial order without any prior notice or opportunity to be heard.",
      "ratio": "The Court reiterated that lease cancellation is a quasi‑judicial act and the audi alteram partem rule must be observed; statutory silence cannot be interpreted as a waiver of natural justice.",
      "decision": "The cancellation order was set aside and the matter was directed to the appropriate authority for a hearing.",
      "relevance_to_query": "A recent affirmation that even today, mining lease cancellations require compliance with natural justice."
    },
    "status": "good_law"
  },
  {
    "title": "M/s. Hindustan Copper Ltd. v. Union of India",
    "citation": "(2005) 6 SCC 1",
    "year": 2005,
    "summary": {
      "issue": "Renewal of a mining lease and the necessity of a hearing before denial of renewal.",
      "material_facts": "The government denied renewal of Hindustan Copper’s lease for a copper mine without providing any hearing.",
      "ratio": "The Court held that denial of renewal is equivalent to cancellation and thus attracts the same requirement of audi alteram partem.",
      "decision": "The denial was set aside; the lease renewal was ordered after a proper hearing.",
      "relevance_to_query": "Extends the principle to renewal/denial scenarios, underscoring that any adverse decision on a mining lease must be preceded by a hearing."
    },
    "status": "good_law"
  }
]
